{const rows=window.CDD;const topics=document.querySelector('.topics');topics.replaceChildren();for(const t of ['all',...new Set(rows.map(x=>x.topic).sort())]){const b=document.createElement('button');b.dataset.topic=t;b.textContent=t==='all'?'All topics':t;if(t==='all')b.className='active';topics.append(b)}const details=document.createElement('details');details.className='hint';const summary=document.createElement('summary');summary.textContent='Topic coverage and depth limits';details.append(summary);const p=document.createElement('p');p.textContent='Major Linux admin/interview areas are represented below. Entry counts measure catalog size, not mastery or exhaustive coverage. Cloud, databases, automation and VMs are adjacent admin skills. Interview practice is generic guidance, not personal claims.';details.append(p);for(const t of [...new Set(rows.map(x=>x.topic).sort())]){const p=document.createElement('p');p.textContent=t+': '+rows.filter(x=>x.topic===t).length+' entries';details.append(p)}const gap=document.createElement('p');gap.textContent='Depth still to build: kernel development/debugging, eBPF, advanced routing/VPN, Btrfs/ZFS, high availability/clustering, mail/DNS server operation, Kubernetes, advanced SELinux policy, database recovery/replication and distro-specific installers. This is a broad learning reference, not every Linux concept.';details.append(gap);document.getElementById('filters').before(details);}